-- LUXE PERFUME V1: MySQL 8.4 / InnoDB / utf8mb4. Monetary values are DECIMAL.
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, description VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(role_id,permission_id), CONSTRAINT fk_rp_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, CONSTRAINT fk_rp_permission FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255), first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100), phone VARCHAR(30), auth_provider VARCHAR(30) NOT NULL DEFAULT 'LOCAL', provider_subject VARCHAR(191), account_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', email_verified_at DATETIME, last_login_at DATETIME, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME, UNIQUE KEY uk_user_provider_subject(auth_provider,provider_subject), KEY idx_user_status_created(account_status,created_at), CONSTRAINT chk_user_provider CHECK(auth_provider IN ('LOCAL','GOOGLE')), CONSTRAINT chk_user_status CHECK(account_status IN ('PENDING','ACTIVE','SUSPENDED','CLOSED')), CONSTRAINT chk_local_password CHECK(auth_provider <> 'LOCAL' OR password_hash IS NOT NULL)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,role_id), CONSTRAINT fk_ur_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_ur_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, label VARCHAR(50), recipient_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, address_line1 VARCHAR(255) NOT NULL, address_line2 VARCHAR(255), area VARCHAR(120), city VARCHAR(120) NOT NULL, district VARCHAR(120), postal_code VARCHAR(20), country_code CHAR(2) NOT NULL DEFAULT 'BD', is_default BOOLEAN NOT NULL DEFAULT FALSE, default_user_id BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN is_default=TRUE THEN user_id ELSE NULL END) VIRTUAL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_one_default_address(default_user_id), KEY idx_addresses_user(user_id), CONSTRAINT fk_addresses_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE brands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(150) NOT NULL UNIQUE, description TEXT, logo_url VARCHAR(1000), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED, name VARCHAR(120) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, description TEXT, image_url VARCHAR(1000), sort_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_categories_parent_sort(parent_id,sort_order), CONSTRAINT fk_categories_parent FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE collections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, slug VARCHAR(170) NOT NULL UNIQUE, description TEXT, cover_image_url VARCHAR(1000), starts_at DATETIME, ends_at DATETIME, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT chk_collection_dates CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, brand_id BIGINT UNSIGNED, name VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, short_description VARCHAR(500), description LONGTEXT, product_type VARCHAR(30) NOT NULL DEFAULT 'STANDARD', status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', is_featured BOOLEAN NOT NULL DEFAULT FALSE, seo_title VARCHAR(255), seo_description VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME, KEY idx_products_category_status(category_id,status), KEY idx_products_brand_status(brand_id,status), KEY idx_products_featured_status(is_featured,status), CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT, CONSTRAINT fk_products_brand FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE SET NULL, CONSTRAINT chk_product_type CHECK(product_type IN ('STANDARD','VARIABLE')), CONSTRAINT chk_product_status CHECK(status IN ('DRAFT','ACTIVE','ARCHIVED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, image_url VARCHAR(1000) NOT NULL, alt_text VARCHAR(255), sort_order INT NOT NULL DEFAULT 0, is_primary BOOLEAN NOT NULL DEFAULT FALSE, primary_product_id BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN is_primary=TRUE THEN product_id ELSE NULL END) VIRTUAL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_one_primary_product_image(primary_product_id), KEY idx_product_images_product_sort(product_id,sort_order), CONSTRAINT fk_product_images_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, sku VARCHAR(80) NOT NULL UNIQUE, variant_name VARCHAR(120) NOT NULL, option_values JSON, volume_ml DECIMAL(8,2), price DECIMAL(12,2) NOT NULL, compare_at_price DECIMAL(12,2), cost_price DECIMAL(12,2), weight_grams DECIMAL(10,2), is_default BOOLEAN NOT NULL DEFAULT FALSE, default_product_id BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN is_default=TRUE THEN product_id ELSE NULL END) VIRTUAL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_one_default_variant(default_product_id), KEY idx_variants_product_active(product_id,is_active), CONSTRAINT fk_variants_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT chk_variant_price CHECK(price >= 0), CONSTRAINT chk_variant_compare CHECK(compare_at_price IS NULL OR compare_at_price >= price), CONSTRAINT chk_variant_cost CHECK(cost_price IS NULL OR cost_price >= 0), CONSTRAINT chk_variant_volume CHECK(volume_ml IS NULL OR volume_ml > 0), CONSTRAINT chk_variant_weight CHECK(weight_grams IS NULL OR weight_grams >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE collection_products (collection_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, sort_order INT NOT NULL DEFAULT 0, added_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(collection_id,product_id), KEY idx_collection_products_product(product_id), CONSTRAINT fk_cp_collection FOREIGN KEY(collection_id) REFERENCES collections(id) ON DELETE CASCADE, CONSTRAINT fk_cp_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE carts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, cart_status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', active_user_id BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN cart_status='ACTIVE' THEN user_id ELSE NULL END) VIRTUAL, currency CHAR(3) NOT NULL DEFAULT 'BDT', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_one_active_cart_per_user(active_user_id), KEY idx_carts_user_status(user_id,cart_status), CONSTRAINT fk_carts_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT chk_cart_status CHECK(cart_status IN ('ACTIVE','CONVERTED','ABANDONED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE cart_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cart_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, added_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_cart_variant(cart_id,variant_id), KEY idx_cart_items_variant(variant_id), CONSTRAINT fk_cart_items_cart FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, CONSTRAINT fk_cart_items_variant FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT, CONSTRAINT chk_cart_quantity CHECK(quantity > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE wishlists (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL DEFAULT 'My Wishlist', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_wishlist_user_name(user_id,name), CONSTRAINT fk_wishlists_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE wishlist_items (wishlist_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, added_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(wishlist_id,product_id), KEY idx_wishlist_product(product_id), CONSTRAINT fk_wi_wishlist FOREIGN KEY(wishlist_id) REFERENCES wishlists(id) ON DELETE CASCADE, CONSTRAINT fk_wi_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, description VARCHAR(255), discount_type VARCHAR(20) NOT NULL, discount_value DECIMAL(12,2) NOT NULL, minimum_order_amount DECIMAL(12,2) NOT NULL DEFAULT 0, maximum_discount_amount DECIMAL(12,2), usage_limit INT UNSIGNED, per_user_limit INT UNSIGNED, usage_count INT UNSIGNED NOT NULL DEFAULT 0, starts_at DATETIME, ends_at DATETIME, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT chk_coupon_type CHECK(discount_type IN ('PERCENTAGE','FIXED')), CONSTRAINT chk_coupon_value CHECK(discount_value > 0), CONSTRAINT chk_coupon_min CHECK(minimum_order_amount >= 0), CONSTRAINT chk_coupon_max CHECK(maximum_discount_amount IS NULL OR maximum_discount_amount > 0), CONSTRAINT chk_coupon_percent CHECK(discount_type <> 'PERCENTAGE' OR discount_value <= 100), CONSTRAINT chk_coupon_dates CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE coupon_products (coupon_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(coupon_id,product_id), CONSTRAINT fk_coupon_products_coupon FOREIGN KEY(coupon_id) REFERENCES coupons(id) ON DELETE CASCADE, CONSTRAINT fk_coupon_products_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE coupon_categories (coupon_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(coupon_id,category_id), CONSTRAINT fk_coupon_categories_coupon FOREIGN KEY(coupon_id) REFERENCES coupons(id) ON DELETE CASCADE, CONSTRAINT fk_coupon_categories_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE inventory (variant_id BIGINT UNSIGNED PRIMARY KEY, quantity_on_hand INT UNSIGNED NOT NULL DEFAULT 0, quantity_reserved INT UNSIGNED NOT NULL DEFAULT 0, reorder_level INT UNSIGNED NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_inventory_variant FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT, CONSTRAINT chk_inventory_reserved CHECK(quantity_reserved <= quantity_on_hand)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE inventory_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, variant_id BIGINT UNSIGNED NOT NULL, movement_type VARCHAR(20) NOT NULL, quantity_change INT NOT NULL, reference_type VARCHAR(30), reference_id BIGINT UNSIGNED, note VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_inventory_movement_variant_date(variant_id,created_at), KEY idx_inventory_movement_reference(reference_type,reference_id), CONSTRAINT fk_inventory_movements_variant FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT, CONSTRAINT chk_inventory_movement_type CHECK(movement_type IN ('RECEIPT','RESERVATION','RELEASE','SALE','ADJUSTMENT','RETURN')), CONSTRAINT chk_inventory_movement_nonzero CHECK(quantity_change <> 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE customer_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(40) NOT NULL UNIQUE, user_id BIGINT UNSIGNED, order_status VARCHAR(24) NOT NULL DEFAULT 'PENDING', payment_status VARCHAR(24) NOT NULL DEFAULT 'UNPAID', currency CHAR(3) NOT NULL DEFAULT 'BDT', subtotal DECIMAL(12,2) NOT NULL, discount_total DECIMAL(12,2) NOT NULL DEFAULT 0, shipping_total DECIMAL(12,2) NOT NULL DEFAULT 0, tax_total DECIMAL(12,2) NOT NULL DEFAULT 0, grand_total DECIMAL(12,2) NOT NULL, coupon_code_snapshot VARCHAR(60), shipping_recipient VARCHAR(150) NOT NULL, shipping_phone VARCHAR(30) NOT NULL, customer_email VARCHAR(254) NOT NULL, shipping_address_line1 VARCHAR(255) NOT NULL, shipping_address_line2 VARCHAR(255), shipping_area VARCHAR(120), shipping_city VARCHAR(120) NOT NULL, shipping_district VARCHAR(120), shipping_postal_code VARCHAR(20), shipping_country_code CHAR(2) NOT NULL DEFAULT 'BD', customer_note VARCHAR(1000), placed_at DATETIME, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_orders_user_date(user_id,created_at), KEY idx_orders_customer_email_date(customer_email,created_at), KEY idx_orders_status_date(order_status,created_at), KEY idx_orders_payment_status(payment_status), CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT chk_order_status CHECK(order_status IN ('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURNED')), CONSTRAINT chk_order_payment_status CHECK(payment_status IN ('UNPAID','PENDING','PAID','FAILED','PARTIALLY_REFUNDED','REFUNDED')), CONSTRAINT chk_order_amounts CHECK(subtotal >= 0 AND discount_total >= 0 AND shipping_total >= 0 AND tax_total >= 0 AND grand_total >= 0), CONSTRAINT chk_order_discount_limit CHECK(discount_total <= subtotal), CONSTRAINT chk_order_total CHECK(grand_total = subtotal - discount_total + shipping_total + tax_total)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, from_status VARCHAR(24), to_status VARCHAR(24) NOT NULL, note VARCHAR(500), changed_by BIGINT UNSIGNED, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_order_status_history_order_date(order_id,created_at), KEY idx_order_status_history_actor(changed_by), CONSTRAINT fk_order_history_order FOREIGN KEY(order_id) REFERENCES customer_orders(id) ON DELETE CASCADE, CONSTRAINT fk_order_history_actor FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT chk_order_history_to CHECK(to_status IN ('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURNED')), CONSTRAINT chk_order_history_from CHECK(from_status IS NULL OR from_status IN ('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURNED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED, product_name_snapshot VARCHAR(200) NOT NULL, variant_name_snapshot VARCHAR(120) NOT NULL, sku_snapshot VARCHAR(80) NOT NULL, unit_price DECIMAL(12,2) NOT NULL, quantity INT UNSIGNED NOT NULL, line_discount DECIMAL(12,2) NOT NULL DEFAULT 0, line_total DECIMAL(12,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_order_items_order(order_id), KEY idx_order_items_variant(variant_id), CONSTRAINT fk_order_items_order FOREIGN KEY(order_id) REFERENCES customer_orders(id) ON DELETE CASCADE, CONSTRAINT fk_order_items_variant FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE SET NULL, CONSTRAINT chk_order_item_quantity CHECK(quantity > 0), CONSTRAINT chk_order_item_amounts CHECK(unit_price >= 0 AND line_discount >= 0 AND line_total >= 0), CONSTRAINT chk_order_item_discount_limit CHECK(line_discount <= unit_price * quantity), CONSTRAINT chk_order_item_total CHECK(line_total = unit_price * quantity - line_discount)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE coupon_redemptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, coupon_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED, order_id BIGINT UNSIGNED NOT NULL UNIQUE, discount_amount DECIMAL(12,2) NOT NULL, redeemed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_coupon_redemptions_user(coupon_id,user_id), CONSTRAINT fk_coupon_redemptions_coupon FOREIGN KEY(coupon_id) REFERENCES coupons(id) ON DELETE RESTRICT, CONSTRAINT fk_coupon_redemptions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_coupon_redemptions_order FOREIGN KEY(order_id) REFERENCES customer_orders(id) ON DELETE CASCADE, CONSTRAINT chk_coupon_redemption_discount CHECK(discount_amount >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(30) NOT NULL, payment_method VARCHAR(30) NOT NULL, provider_transaction_id VARCHAR(150), provider_reference VARCHAR(150), amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'BDT', payment_status VARCHAR(24) NOT NULL DEFAULT 'INITIATED', initiated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME, provider_payload JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_payment_provider_transaction(provider,provider_transaction_id), KEY idx_payments_order_date(order_id,created_at), KEY idx_payments_status(payment_status), CONSTRAINT fk_payments_order FOREIGN KEY(order_id) REFERENCES customer_orders(id) ON DELETE RESTRICT, CONSTRAINT chk_payment_provider CHECK(provider IN ('COD','SSLCOMMERZ','BKASH','NAGAD','MANUAL')), CONSTRAINT chk_payment_method CHECK(payment_method IN ('CASH_ON_DELIVERY','CARD','MOBILE_BANKING','BANK_TRANSFER','OTHER')), CONSTRAINT chk_payment_status CHECK(payment_status IN ('INITIATED','PENDING','AUTHORIZED','PAID','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED')), CONSTRAINT chk_payment_amount CHECK(amount > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED, rating TINYINT UNSIGNED NOT NULL, title VARCHAR(150), body TEXT, moderation_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', moderated_by BIGINT UNSIGNED, moderated_at DATETIME, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_review_user_product(user_id,product_id), KEY idx_reviews_product_status_date(product_id,moderation_status,created_at), KEY idx_reviews_moderator(moderated_by), CONSTRAINT fk_reviews_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT fk_reviews_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_reviews_order_item FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE SET NULL, CONSTRAINT fk_reviews_moderator FOREIGN KEY(moderated_by) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT chk_review_rating CHECK(rating BETWEEN 1 AND 5), CONSTRAINT chk_review_moderation CHECK(moderation_status IN ('PENDING','APPROVED','REJECTED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE banners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, subtitle VARCHAR(255), image_url VARCHAR(1000) NOT NULL, target_url VARCHAR(1000), placement VARCHAR(50) NOT NULL DEFAULT 'HOME_HERO', starts_at DATETIME, ends_at DATETIME, sort_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_banners_placement_active(placement,is_active,sort_order), CONSTRAINT chk_banner_dates CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE newsletter_subscribers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, subscription_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', consented_at DATETIME, confirmed_at DATETIME, unsubscribed_at DATETIME, source VARCHAR(80), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_newsletter_status_created(subscription_status,created_at), CONSTRAINT chk_newsletter_status CHECK(subscription_status IN ('PENDING','SUBSCRIBED','UNSUBSCRIBED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Seed RBAC catalogue; deliberately no default admin/customer account or password.
INSERT INTO roles(code,name,description) VALUES ('CUSTOMER','Customer','Storefront customer'),('ADMIN','Administrator','Full administrative access'),('MANAGER','Manager','Operational management'),('INVENTORY_STAFF','Inventory Staff','Product and stock operations');
INSERT INTO permissions(code,name) VALUES ('dashboard.read','View dashboard'),('products.read','View products'),('products.write','Manage products'),('catalog.write','Manage catalog taxonomy'),('orders.read','View orders'),('orders.write','Manage orders'),('customers.read','View customers'),('inventory.read','View inventory'),('inventory.write','Manage inventory'),('payments.read','View payments'),('promotions.write','Manage promotions'),('reviews.moderate','Moderate reviews'),('newsletter.manage','Manage newsletter'),('staff.manage','Manage staff and roles'),('settings.manage','Manage settings');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='ADMIN';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p WHERE r.code='MANAGER' AND p.code IN ('dashboard.read','products.read','products.write','catalog.write','orders.read','orders.write','customers.read','inventory.read','inventory.write','payments.read','promotions.write','reviews.moderate','newsletter.manage');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p WHERE r.code='INVENTORY_STAFF' AND p.code IN ('dashboard.read','products.read','inventory.read','inventory.write');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p WHERE r.code='CUSTOMER' AND p.code IN ('products.read','orders.read');
